type Lookup func(string) string

func Cached(next Lookup) Lookup {
	cache := make(map[string]string)
	return func(key string) string {
		if value, ok := cache[key]; ok {
			return value
		}
		value := next(key)
		cache[key] = value
		return value
	}
}

func main() {
	calls := 0
	lookup := Cached(func(key string) string { calls++; return "value:" + key })
	fmt.Println(lookup("go"))
	fmt.Println(lookup("go"))
	fmt.Println(calls)
}

