type Rename struct {
	target         *string
	next, previous string
	done           bool
}

func (c *Rename) Do() {
	if c.done {
		return
	}
	c.previous = *c.target
	*c.target = c.next
	c.done = true
}
func (c *Rename) Undo() {
	if !c.done {
		return
	}
	*c.target = c.previous
	c.done = false
}

func main() {
	name := "draft"
	c := &Rename{target: &name, next: "report"}
	c.Do()
	fmt.Println(name)
	c.Undo()
	fmt.Println(name)
