solutions.concurrency.worker-pool:
package main

import "sync"

func Squares(numbers []int, workers int) []int {
	in, out := make(chan int), make(chan int)

	var wg sync.WaitGroup
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for n := range in {
				out <- n * n
			}
		}()
	}

	go func() {
		defer close(in)
		for _, n := range numbers {
			in <- n
		}
	}()

	go func() {
		wg.Wait()
		close(out)
	}()

	results := make([]int, 0, len(numbers))
	for r := range out {
		results = append(results, r)
	}
	return results
}

func main() {}

