package main

type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(value T) {
	// A nil slice appends fine, which is what makes the zero value work.
	s.items = append(s.items, value)
}

func (s *Stack[T]) Pop() (T, bool) {
	if len(s.items) == 0 {
		// The zero value of T, whatever T turned out to be.
		var zero T
		return zero, false
	}
	last := len(s.items) - 1
	value := s.items[last]
	var zero T
	s.items[last] = zero
	s.items = s.items[:last]
	return value, true
}

func main() {
	var s Stack[string]
	s.Push("go")
	value, ok := s.Pop()
	println(value, ok)
}

