	"sort"
	"testing"
)

func TestSquaresReturnsEveryResult(t *testing.T) {
	got := Squares([]int{1, 2, 3, 4, 5}, 3)
	sort.Ints(got)

	want := []int{1, 4, 9, 16, 25}
	if len(got) != len(want) {
		t.Fatalf("got %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v, want %v", got, want)
		}
	}
	if len(Squares(nil, 2)) != 0 {
		t.Error("no input should give no results, and should still return")
	}
}

