func Fill(n int) []int {
	ch := make(chan int, n)
	for i := 0; i < n; i++ {
		ch <- i
	}
	close(ch)
	out := make([]int, 0, n)
	for v := range ch {
		out = append(out, v)
	}
	return out
}

